          await pool.query(`ALTER TABLE competitor_posts ADD CONSTRAINT fk_competitor_profile FOREIGN KEY (profile_id) REFERENCES competitor_profiles(id) ON DELETE CASCADE;`);
        } catch (_e2: any) { /* already exists */ }

